Brief:
A paper kite rides the wind over the rooftops. Tap to rise, avoid the chimneys and collect ribbons while the wind slowly speeds up.

Plan:
{"gameType":"arcade-run","input":"tap-anywhere","lang":"en","loop":"Tap to lift the paper kite over rooftops, dodging chimneys and collecting ribbons as the wind speeds up. Hitting a chimney ends the flight and shows your ribbon tally.","slug":"kite-over-the-rooftops","style":"paper-cut","title":"Kite Over the Rooftops"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Kite Over the Rooftops</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     overflow: hidden;
14|     background: #f4ecd8;
15|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
16|   }
17|   canvas {
18|     display: block;
19|     touch-action: none;
20|   }
21| </style>
22| </head>
23| <body>
24| <canvas id="game"></canvas>
25| <script>
26| // ---- Bridge helper (verbatim) ----
27| const CARTRIDGE = {
28|   send(type, payload = {}) {
29|     window.parent.postMessage(
30|       { source: "cartridge", v: 1, type, payload },
31|       "*",
32|     );
33|   },
34| };
35| </script>
36| <script>
37| (function () {
38|   "use strict";
39| 
40|   const canvas = document.getElementById("game");
41|   const ctx = canvas.getContext("2d");
42| 
43|   // ---- Sizing ----
44|   let W = 0, H = 0, DPR = 1;
45|   function resize() {
46|     DPR = window.devicePixelRatio || 1;
47|     W = window.innerWidth;
48|     H = window.innerHeight;
49|     canvas.width = Math.round(W * DPR);
50|     canvas.height = Math.round(H * DPR);
51|     canvas.style.width = W + "px";
52|     canvas.style.height = H + "px";
53|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
54|   }
55|   window.addEventListener("resize", resize);
56|   resize();
57| 
58|   // ---- Palette ----
59|   const COL_BG = "#f4ecd8";
60|   const COL_LAYER = "#e07a5f";
61|   const COL_ACCENT = "#3d405b";
62|   const COL_HILITE = "#81b29a";
63| 
64|   // ---- Seeded jitter helper ----
65|   function makeRng(seed) {
66|     let s = seed >>> 0;
67|     return function () {
68|       s = (s * 1664525 + 1013904223) >>> 0;
69|       return s / 4294967296;
70|     };
71|   }
72|   const rng = makeRng(20240521);
73|   function jitter(n) {
74|     return (rng() - 0.5) * n;
75|   }
76| 
77|   // Precompute a jittered polygon for reuse (seeded once, cached per shape id)
78|   const jitterCache = {};
79|   function jitteredPoints(id, pts, amt) {
80|     if (jitterCache[id]) return jitterCache[id];
81|     const out = pts.map(([x, y]) => [x + jitter(amt), y + jitter(amt)]);
82|     jitterCache[id] = out;
83|     return out;
84|   }
85| 
86|   function drawPaperPath(id, pts, amt, fillStyle, shadow) {
87|     const jp = jitteredPoints(id, pts, amt);
88|     ctx.save();
89|     if (shadow) {
90|       ctx.shadowColor = "rgba(61,64,91,0.35)";
91|       ctx.shadowBlur = 6;
92|       ctx.shadowOffsetX = 1;
93|       ctx.shadowOffsetY = 3;
94|     }
95|     ctx.beginPath();
96|     ctx.moveTo(jp[0][0], jp[0][1]);
97|     for (let i = 1; i < jp.length; i++) ctx.lineTo(jp[i][0], jp[i][1]);
98|     ctx.closePath();
99|     ctx.fillStyle = fillStyle;
100|     ctx.fill();
101|     ctx.restore();
102|   }
103| 
104|   function roundRectPath(x, y, w, h, r) {
105|     ctx.beginPath();
106|     ctx.moveTo(x + r, y);
107|     ctx.lineTo(x + w - r, y);
108|     ctx.quadraticCurveTo(x + w, y, x + w, y + r);
109|     ctx.lineTo(x + w, y + h - r);
110|     ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
111|     ctx.lineTo(x + r, y + h);
112|     ctx.quadraticCurveTo(x, y + h, x, y + h - r);
113|     ctx.lineTo(x, y + r);
114|     ctx.quadraticCurveTo(x, y, x + r, y);
115|     ctx.closePath();
116|   }
117| 
118|   // ---- Game state ----
119|   let last = 0;
120|   let running = false;
121|   let paused = false;
122|   let started = false; // has boot been sent / has first frame drawn
123|   let score = 0;
124|   let ribbons = 0;
125|   let speed = 160; // px/sec base scroll speed
126|   let elapsed = 0;
127|   let bootSent = false;
128|   let firstTapDone = false;
129| 
130|   // Kite (player)
131|   const kite = {
132|     x: 0,
133|     y: 0,
134|     vy: 0,
135|     r: 18,
136|   };
137| 
138|   function resetKite() {
139|     kite.x = W * 0.28;
140|     kite.y = H * 0.4;
141|     kite.vy = 0;
142|   }
143| 
144|   // Rooftop chimneys (hazards) and ribbons (collectibles)
145|   let chimneys = [];
146|   let ribbonsList = [];
147|   let spawnTimer = 0;
148|   let ribbonSpawnTimer = 0;
149|   let rooftopY = 0;
150| 
151|   function backToTitle() {
152|     running = false;
153|     paused = false;
154|     started = false;
155|     score = 0;
156|     ribbons = 0;
157|     speed = 160;
158|     elapsed = 0;
159|     chimneys = [];
160|     ribbonsList = [];
161|     spawnTimer = 0;
162|     ribbonSpawnTimer = 0;
163|     resetKite();
164|   }
165| 
166|   function computeRooftop() {
167|     rooftopY = H * 0.82;
168|   }
169| 
170|   resetKite();
171|   computeRooftop();
172| 
173|   function spawnChimney(xOverride) {
174|     const w = 30 + rng() * 18;
175|     const h = 40 + rng() * 60;
176|     const x = xOverride !== undefined ? xOverride : W + 40;
177|     chimneys.push({ x, w, h, id: Math.floor(rng() * 1e9) });
178|   }
179| 
180|   function spawnRibbon() {
181|     const y = H * 0.15 + rng() * (H * 0.5);
182|     ribbonsList.push({ x: W + 30, y, id: Math.floor(rng() * 1e9), taken: false });
183|   }
184| 
185|   // Fairness: keep opening lane clear, spawn first hazard well ahead
186|   let openingGraceDistance = 0;
187| 
188|   function startPlay() {
189|     chimneys = [];
190|     ribbonsList = [];
191|     spawnTimer = 0;
192|     ribbonSpawnTimer = 0;
193|     score = 0;
194|     ribbons = 0;
195|     speed = 160;
196|     elapsed = 0;
197|     resetKite();
198|     // first hazard spawns well off to the right, giving a few seconds of clear flight
199|     spawnChimney(W + W * 0.9);
200|     CARTRIDGE.send("score", { value: score });
201|   }
202| 
203|   function crash() {
204|     if (!running) return;
205|     running = false;
206|     CARTRIDGE.send("end", { reason: "lose", value: score });
207|   }
208| 
209|   // ---- Input ----
210|   canvas.style.touchAction = "none";
211|   canvas.addEventListener("pointerdown", (event) => {
212|     event.preventDefault();
213|     if (paused) return;
214|     if (!running) {
215|       running = true;
216|       firstTapDone = true;
217|       startPlay();
218|       CARTRIDGE.send("start");
219|       return;
220|     }
221|     act();
222|   });
223| 
224|   function act() {
225|     kite.vy = -260;
226|   }
227| 
228|   // ---- Host messages ----
229|   window.addEventListener("message", (event) => {
230|     const data = event.data;
231|     if (!data || data.source !== "cartridge-host") return;
232|     if (data.type === "pause") paused = true;
233|     if (data.type === "resume") paused = false;
234|     if (data.type === "reset") backToTitle();
235|   });
236| 
237|   // ---- Update ----
238|   function advance(dt) {
239|     elapsed += dt;
240|     speed += dt * 4; // ramp difficulty via speed
241| 
242|     // gravity + lift
243|     kite.vy += 420 * dt;
244|     kite.y += kite.vy * dt;
245| 
246|     const ceiling = H * 0.06;
247|     const floor = rooftopY - kite.r;
248|     if (kite.y < ceiling) {
249|       kite.y = ceiling;
250|       kite.vy = 0;
251|     }
252|     if (kite.y > floor) {
253|       kite.y = floor;
254|       kite.vy = 0;
255|       crash();
256|       return;
257|     }
258| 
259|     // spawn chimneys
260|     spawnTimer -= dt;
261|     if (spawnTimer <= 0) {
262|       spawnChimney();
263|       spawnTimer = 1.4 + rng() * 0.9 - Math.min(elapsed * 0.01, 0.6);
264|       if (spawnTimer < 0.7) spawnTimer = 0.7;
265|     }
266| 
267|     // spawn ribbons
268|     ribbonSpawnTimer -= dt;
269|     if (ribbonSpawnTimer <= 0) {
270|       spawnRibbon();
271|       ribbonSpawnTimer = 1.6 + rng() * 1.2;
272|     }
273| 
274|     // move chimneys
275|     for (const c of chimneys) {
276|       c.x -= speed * dt;
277|     }
278|     chimneys = chimneys.filter((c) => c.x + c.w > -20);
279| 
280|     // move ribbons
281|     for (const r of ribbonsList) {
282|       r.x -= speed * dt;
283|     }
284|     ribbonsList = ribbonsList.filter((r) => r.x > -20 && !r.taken);
285|   }
286| 
287|   function collide() {
288|     // chimney collision (rects rising from rooftop)
289|     for (const c of chimneys) {
290|       const top = rooftopY - c.h;
291|       const left = c.x;
292|       const right = c.x + c.w;
293|       if (
294|         kite.x + kite.r * 0.7 > left &&
295|         kite.x - kite.r * 0.7 < right &&
296|         kite.y + kite.r * 0.7 > top
297|       ) {
298|         crash();
299|         return;
300|       }
301|     }
302|     // ribbon collection
303|     for (const r of ribbonsList) {
304|       if (r.taken) continue;
305|       const dx = kite.x - r.x;
306|       const dy = kite.y - r.y;
307|       const dist = Math.sqrt(dx * dx + dy * dy);
308|       if (dist < kite.r + 12) {
309|         r.taken = true;
310|         ribbons += 1;
311|         score += 10;
312|         CARTRIDGE.send("score", { value: score });
313|       }
314|     }
315|   }
316| 
317|   // ---- Drawing ----
318|   let cloudPhase = 0;
319| 
320|   function drawBackground(dt) {
321|     ctx.fillStyle = COL_BG;
322|     ctx.fillRect(0, 0, W, H);
323| 
324|     // drifting clouds (keep motion visible while idle)
325|     cloudPhase += dt * 12;
326|     ctx.save();
327|     ctx.globalAlpha = 0.55;
328|     for (let i = 0; i < 4; i++) {
329|       const cx = ((i * 220 + cloudPhase) % (W + 200)) - 100;
330|       const cy = H * 0.15 + i * 40;
331|       drawCloud(`cloud${i}`, cx, cy, 40 + i * 6);
332|     }
333|     ctx.restore();
334|   }
335| 
336|   function drawCloud(id, x, y, r) {
337|     const pts = [
338|       [x - r, y],
339|       [x - r * 0.5, y - r * 0.6],
340|       [x, y - r * 0.7],
341|       [x + r * 0.5, y - r * 0.5],
342|       [x + r, y],
343|       [x + r * 0.6, y + r * 0.4],
344|       [x - r * 0.6, y + r * 0.4],
345|     ];
346|     drawPaperPath(id + "_" + Math.round(x / 50), pts, 3, "#ffffff", false);
347|   }
348| 
349|   function drawRooftops() {
350|     // rooftop base layer
351|     ctx.save();
352|     ctx.shadowColor = "rgba(61,64,91,0.3)";
353|     ctx.shadowBlur = 6;
354|     ctx.shadowOffsetY = 3;
355|     ctx.fillStyle = COL_LAYER;
356|     ctx.fillRect(0, rooftopY, W, H - rooftopY);
357|     ctx.restore();
358| 
359|     // roof ridge line (accent strip)
360|     ctx.fillStyle = COL_ACCENT;
361|     ctx.fillRect(0, rooftopY, W, 4);
362|   }
363| 
364|   function drawChimney(c) {
365|     const top = rooftopY - c.h;
366|     const id = "chim" + c.id;
367|     const pts = [
368|       [c.x, rooftopY],
369|       [c.x, top],
370|       [c.x + c.w, top],
371|       [c.x + c.w, rooftopY],
372|     ];
373|     drawPaperPath(id, pts, 2, COL_ACCENT, true);
374|     // little cap
375|     ctx.fillStyle = COL_LAYER;
376|     ctx.fillRect(c.x - 3, top - 6, c.w + 6, 8);
377|   }
378| 
379|   function drawRibbon(r) {
380|     if (r.taken) return;
381|     ctx.save();
382|     ctx.translate(r.x, r.y);
383|     ctx.shadowColor = "rgba(61,64,91,0.25)";
384|     ctx.shadowBlur = 5;
385|     ctx.shadowOffsetY = 2;
386|     ctx.fillStyle = COL_HILITE;
387|     // simple ribbon shape: two triangles + circle knot
388|     ctx.beginPath();
389|     ctx.moveTo(-10, -4);
390|     ctx.lineTo(-2, 0);
391|     ctx.lineTo(-10, 10);
392|     ctx.closePath();
393|     ctx.fill();
394|     ctx.beginPath();
395|     ctx.moveTo(10, -4);
396|     ctx.lineTo(2, 0);
397|     ctx.lineTo(10, 10);
398|     ctx.closePath();
399|     ctx.fill();
400|     ctx.beginPath();
401|     ctx.arc(0, -2, 6, 0, Math.PI * 2);
402|     ctx.fill();
403|     ctx.restore();
404|   }
405| 
406|   function drawKite() {
407|     ctx.save();
408|     ctx.translate(kite.x, kite.y);
409|     const angle = Math.max(-0.3, Math.min(0.5, kite.vy * 0.0006));
410|     ctx.rotate(angle);
411| 
412|     // tail
413|     ctx.strokeStyle = COL_ACCENT;
414|     ctx.lineWidth = 2;
415|     ctx.beginPath();
416|     ctx.moveTo(0, kite.r * 0.8);
417|     ctx.quadraticCurveTo(-6, kite.r * 1.6, 4, kite.r * 2.2);
418|     ctx.stroke();
419| 
420|     // kite diamond body (paper-cut style, jittered once per shape)
421|     const r = kite.r;
422|     const pts = [
423|       [0, -r * 1.3],
424|       [r, 0],
425|       [0, r * 1.3],
426|       [-r, 0],
427|     ];
428|     drawPaperPath("kitebody", pts, 2, COL_LAYER, true);
429| 
430|     // cross spar accent
431|     ctx.strokeStyle = COL_ACCENT;
432|     ctx.lineWidth = 1.5;
433|     ctx.beginPath();
434|     ctx.moveTo(0, -r * 1.3);
435|     ctx.lineTo(0, r * 1.3);
436|     ctx.moveTo(-r, 0);
437|     ctx.lineTo(r, 0);
438|     ctx.stroke();
439| 
440|     ctx.restore();
441|   }
442| 
443|   function drawCard(text, x, y, w, h, fontSize) {
444|     ctx.save();
445|     ctx.shadowColor = "rgba(61,64,91,0.3)";
446|     ctx.shadowBlur = 6;
447|     ctx.shadowOffsetY = 3;
448|     ctx.fillStyle = COL_BG;
449|     roundRectPath(x, y, w, h, 10);
450|     ctx.fill();
451|     ctx.restore();
452| 
453|     ctx.fillStyle = COL_ACCENT;
454|     ctx.font = `700 ${fontSize}px -apple-system, Segoe UI, Roboto, Arial, sans-serif`;
455|     ctx.textAlign = "center";
456|     ctx.textBaseline = "middle";
457|     ctx.fillText(text, x + w / 2, y + h / 2 + 1);
458|   }
459| 
460|   function drawHUD() {
461|     const text = `Ribbons: ${ribbons}`;
462|     const w = Math.max(140, text.length * 12);
463|     drawCard(text, 12, 12, w, 40, 18);
464|   }
465| 
466|   function drawTitleScreen() {
467|     const pulse = 0.6 + 0.4 * Math.sin(elapsed * 3);
468|     ctx.save();
469|     ctx.globalAlpha = pulse;
470|     const w = Math.min(320, W * 0.8);
471|     drawCard("Tap to begin", W / 2 - w / 2, H / 2 - 30, w, 60, 22);
472|     ctx.restore();
473| 
474|     const w2 = Math.min(360, W * 0.85);
475|     drawCard("Kite Over the Rooftops", W / 2 - w2 / 2, H * 0.28 - 30, w2, 60, 20);
476|   }
477| 
478|   function drawEndScreen() {
479|     const w = Math.min(340, W * 0.85);
480|     drawCard(`Flight over! Ribbons: ${ribbons}`, W / 2 - w / 2, H / 2 - 30, w, 60, 20);
481|     const w2 = Math.min(260, W * 0.7);
482|     drawCard("Tap to fly again", W / 2 - w2 / 2, H / 2 + 45, w2, 44, 16);
483|   }
484| 
485|   function draw(dt) {
486|     drawBackground(dt);
487|     drawRooftops();
488|     for (const c of chimneys) drawChimney(c);
489|     for (const r of ribbonsList) drawRibbon(r);
490|     drawKite();
491| 
492|     if (running) {
493|       drawHUD();
494|     } else if (!firstTapDone) {
495|       drawTitleScreen();
496|     } else {
497|       drawEndScreen();
498|     }
499| 
500|     if (paused) {
501|       ctx.save();
502|       ctx.fillStyle = "rgba(61,64,91,0.35)";
503|       ctx.fillRect(0, 0, W, H);
504|       const w = Math.min(220, W * 0.6);
505|       drawCard("Paused", W / 2 - w / 2, H / 2 - 25, w, 50, 20);
506|       ctx.restore();
507|     }
508|   }
509| 
510|   // reposition kite/rooftop after resize while idle/paused too
511|   window.addEventListener("resize", () => {
512|     computeRooftop();
513|     if (!running) resetKite();
514|   });
515| 
516|   // ---- Main loop ----
517|   function frame(now) {
518|     if (!last) last = now;
519|     const dt = Math.min((now - last) / 1000, 0.05);
520|     last = now;
521| 
522|     if (running && !paused) {
523|       advance(dt);
524|       if (running) collide();
525|     }
526| 
527|     draw(dt);
528| 
529|     if (!bootSent) {
530|       bootSent = true;
531|       CARTRIDGE.send("boot", {
532|         title: "Kite Over the Rooftops",
533|         gameType: "arcade-run",
534|         lang: "en",
535|       });
536|     }
537| 
538|     requestAnimationFrame(frame);
539|   }
540| 
541|   requestAnimationFrame(frame);
542| })();
543| </script>
544| </body>
545| </html>
546|

